// doc: Python dict literal semantics:
// doc: - A dict literal written as {k1: v1, k2: v2, ...} produces a mapping whose iteration order
// doc:   is the order in which the keys last occur in the literal. If a key appears multiple
// doc:   times in the literal, the resulting mapping contains the value from the last occurrence,
// doc:   and the key's position in the dict's iteration order corresponds to that last occurrence.
// doc: - More generally, Python dicts preserve insertion order: keys appear when iterating in the
// doc:   order in which they were first inserted (or in the position of their last literal occurrence
// doc:   when created from a literal as above).
// doc: - Keys inserted into a dict must be hashable in Python; this library theory models dicts
// doc:   abstractly and does not attempt to model hashing or unhashability errors raised at runtime.
class PyDict<K, V> {
  // doc: The PyDict type is an abstract model of Python's dict mapping K->V. It stores an explicit
  // doc: sequence of (key,value) pairs describing the dict's logical iteration order. This sequence
  // doc: represents the dict's .items() iteration order: each key appears at most once in that sequence,
  // doc: and the value associated with the key is the value in the pair.
  var itemsSeq: seq<(K, V)>

  // doc: Construct a PyDict by supplying its items in the desired iteration order (a sequence of
  // doc: distinct keys). The caller is responsible for ensuring the supplied sequence has no duplicate
  // doc: keys; Python's literal-to-dict semantics (deduplication with last occurrence winning) is
  // doc: provided by the FromLiteral factory below.
  constructor (initItems: seq<(K, V)>) 
    ensures itemsSeq == initItems
  {
    itemsSeq := initItems;
  }

  // doc: Return the sequence of (key, value) pairs that represents the dict's .items() iteration
  // doc: order. Python's dict.items() returns a view object that yields (key, value) pairs in insertion order;
  // doc: here we model that view by returning the stored sequence. Iterating over this sequence corresponds
  // doc: to iterating over the dict in Python. If the underlying dict is mutated during iteration in CPython,
  // doc: Python raises a RuntimeError ("dictionary changed size during iteration"); this model does not
  // doc: attempt to model that runtime check, but client code should assume that mutating a PyDict while
  // doc: iterating it is an unsupported operation analogous to Python's RuntimeError.
  method Items() returns (s: seq<(K, V)>)
    ensures s == itemsSeq
  {
    s := itemsSeq;
  }

  // doc: Python dict literal creation from a sequence of (key,value) pairs:
  // doc: - When a Python dict is created from an explicit literal source (or equivalently from a list of
  // doc:   pairs), if a key appears multiple times the last occurrence determines the mapping's value and
  // doc:   the key's iteration position is that of the last occurrence.
  // doc: - FromLiteral models constructing a PyDict from a concrete sequence of pairs as if they were the
  // doc:   textual ordering in the literal: the resulting PyDict.Items() equals DedupPairs(pairs) (see
  // doc:   DedupPairs below for the precise deduplication rule).
  static method FromLiteral(pairs: seq<(K, V)>) returns (d: PyDict<K,V>)
    ensures d.itemsSeq == DedupPairs(pairs)
  {
    d := new PyDict<K,V>(DedupPairs(pairs));
  }
}

