// if s[i] is a letter, reverse its case from lower to upper or vise versa, 
// otherwise keep it as it is.
// If the string contains no letters, reverse the string.
// The function should return the resulted string."
method solve(s: string) returns (result: string)
  // synth: frozen precondition (from phase 0b)
  requires s != ""
  // synth: postcondition from assert: assert all((ch.isalpha() and ch.swapcase() == s[i] or (not ch.isalpha() and (ch == s[i] or ch == s[-(i + 1)])) for i, ch in enumerate(return_value)))
  ensures (forall i :: 0 <= i < |PythonStringLib.IterChars(result)| ==>
    var ch := PythonStringLib.IterChars(result)[i];
    (PythonStringLib.IsAlpha(ch) &&
       ((PythonStringLib.IsLower(ch) && PythonStringLib.Upper(ch) == PythonStringLib.IterChars(s)[i]) ||
        (!PythonStringLib.IsLower(ch) && PythonStringLib.Lower(ch) == PythonStringLib.IterChars(s)[i])))
    ||
    (!PythonStringLib.IsAlpha(ch) &&
       (ch == PythonStringLib.IterChars(s)[i] ||
        ch == PythonStringLib.IterChars(s)[|PythonStringLib.IterChars(s)| - (i + 1)])))
{
  // src: source.py:2 |     rev = s[::-1]
  var rev := PythonStringLib.PySliceReverse(s);

  // src: source.py:3 |     new_str = ''
  var new_str := "";

  // synth: helper: materialize characters of rev for indexed iteration
  var revChars := PythonStringLib.IterChars(rev);
  // synth: helper: loop index for translating Python 'for i in rev:'
  var idx := 0;
  // src: source.py:4 |     for i in rev:
  while idx < |revChars|
    // synth: loop invariant omitted (allowed); preserving control flow shape
  {
    // synth: helper: current iteration variable 'i'
    var i := revChars[idx];

    // src: source.py:5 |         if i.isalpha():
    if PythonStringLib.IsAlpha(i) {
      // src: source.py:6 |             if i.islower():
      if PythonStringLib.IsLower(i) {
        // src: source.py:7 |                 new_str += i.upper()
        new_str := PythonStringLib.PyConcat(new_str, PythonStringLib.Upper(i));
      } else {
        // src: source.py:8 |             else:
        // src: source.py:9 |                 new_str += i.lower()
        new_str := PythonStringLib.PyConcat(new_str, PythonStringLib.Lower(i));
      }
    } else {
      // src: source.py:10 |         else:
      // src: source.py:11 |             new_str += i
      new_str := PythonStringLib.PyConcat(new_str, i);
    }

    // synth: increment loop index
    idx := idx + 1;
  }

  // src: source.py:12 |     return new_str
  result := new_str;
  return;
}
